    // calculate result
    long afterStart = instant - overlapStart;
    if (afterStart >= diff) {
      // currently in later offset
      return earlierOrLater ? instant : instant - diff;
    } else {
      // currently in earlier offset
      return earlierOrLater ? instant + diff : instant;
    }
}

